(()=>{const out={pills:[],hits:[]};
 document.querySelectorAll('.map-pill').forEach(p=>{const r=p.getBoundingClientRect();
   out.pills.push({map:p.dataset.map,rect:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)],
                   offsetParent:p.offsetParent?p.offsetParent.id||p.offsetParent.className:null,
                   vis:getComputedStyle(p).visibility,pe:getComputedStyle(p).pointerEvents});});
 const p=document.querySelector('.map-pill[data-map="nes-adventure"]');
 if(p){const r=p.getBoundingClientRect();const cx=r.x+r.width/2,cy=r.y+r.height/2;
   const el=document.elementFromPoint(cx,cy);
   out.clickPoint=[Math.round(cx),Math.round(cy)];
   out.topEl=el?{tag:el.tagName,cls:el.className,id:el.id}:null;
   out.stack=(document.elementsFromPoint(cx,cy)||[]).slice(0,5).map(e=>e.tagName+'.'+(e.className||e.id));}
 out.pickerCount=document.querySelectorAll('#map-picker').length;
 out.tabCount=document.querySelectorAll('.map-pill').length;
 return JSON.stringify(out);})()
